-- Reglages SISIA a (re)appliquer apres une migration ou un remplacement de la base (entity 1 = SISIA ; 0 = global pour l'ecran de connexion).
-- Rejouable sans risque : chaque ligne supprime puis recree la constante.
DELETE FROM llx_const WHERE entity IN (0,1) AND name IN ('MAIN_DOCUMENTS_LOGO_HEIGHT','MAIN_PDF_USE_LARGE_LOGO','MAIN_ADD_PDF_BACKGROUND','MAIN_USE_BACKGROUND_ON_PDF','MAIN_USE_BACKGROUND_ON_PDF_X','MAIN_USE_BACKGROUND_ON_PDF_Y','FACTURE_ADDON_PDF','PROPALE_ADDON_PDF','MAIN_FAVICON_URL','MAIN_HTML_HEADER','MAIN_HTML_FOOTER','THEME_ELDY_ENABLE_PERSONALIZED','THEME_ELDY_TOPMENU_BACK1','THEME_ELDY_VERMENU_BACK1','THEME_ELDY_BACKTITLE1','THEME_ELDY_TEXTTITLE','THEME_ELDY_TEXTTITLENOTAB','THEME_ELDY_TEXTTITLELINK','THEME_ELDY_TEXTLINK','THEME_ELDY_BTNACTION','THEME_ELDY_TEXTBTNACTION','THEME_ELDY_TOPBORDER_TITLE1','THEME_ELDY_USE_HOVER','THEME_ELDY_USE_CHECKED','THEME_ELDY_BACKBODY','THEME_FONT_FAMILY','MAIN_LOGIN_BACKGROUND');
